from global_vars import REPLAYPATH
import os
import torch
import pandas as pd
import json
import numpy as np

class LossCollector:
    show_digits = 5
    max_rows = 1_000_000
    inputnames: list[str] = [
        "state", # (n_parallel x replay_length, n_symmetries, 9) ⋅ write_loss_period
        "actions", # (n_parallel, replay_length-1, n_symmetries) ⋅ write_loss_period
        "turn", # same as ↗, same for ↙
        "rewards", 
        "game_id", 
    ]

    # values generated by model inference and label values
    outputnames: list[str] = [
        "values", #(n_parallel, replay_length-1, n_symmetries) ⋅ write_loss_period
        "Vlabels", # same as ↗, same for ↙
        "advantage", 
        "prob", # (n_parallel, replay_length, n_symmetries, 9) ⋅ write_loss_period
        "log_prob", # (n_parallel, replay_length-1, n_symmetries) ⋅ write_loss_period
        "Pi_grads", # (n_parallel, replay_length-1, n_symmetries) ⋅ write_loss_period
        ]

    # scalar loss values
    lossnames: list[str] = [
        "Pi_loss", # (1) ⋅ write_loss_period
        "V_loss", # same as ↗, same for ↙
        "entropy_loss",
    ]

    def __init__(self):
        # values fed into the model
        self.empty()
        self.memmaps: None | dict[str,np.memmap] = None
        self.steps_taken = 0

    def last_loss(self)->str:
        result = ""
        for name, item in zip(self.lossnames, self.lossitems):
            number_in_str = f"{item[-1].item():.{self.show_digits}g}"
            result+=f"{name}: {number_in_str:<{self.show_digits+7}}"
        return result
    
    def append(self, inputs: list[torch.Tensor], outputs: list[torch.Tensor], loss: list[torch.Tensor]):
        for (id_str, names, items), args in zip(self.wrapped, [inputs, outputs, loss]):
            if len(args) != len(names):
                raise Exception(f"argument {id_str} is of wrong length, requires: {names}")
            for item, arg in zip(items, args):
                item.append(arg)
        self.write_loss_period+=1

    def empty(self):
        self.write_loss_period = 0
        self.inputitems: list[list[torch.Tensor]] = [[] for _ in self.inputnames]
        self.outputitems: list[list[torch.Tensor]] = [[] for _ in self.outputnames]
        self.lossitems: list[list[torch.Tensor]] = [[] for _ in self.lossnames]
        self.wrapped = [("inputs", self.inputnames, self.inputitems), ("outputs", self.outputnames, self.outputitems), ("loss", self.lossnames, self.lossitems)]

    def write(self):
        inputs = [torch.stack(items).cpu().numpy() for items in self.inputitems]  # (write_loss_period, *shape) ⋅ n_names
        outputs = [torch.stack(items).cpu().numpy() for items in self.outputitems] # same as ↗
        loss = [torch.stack(items).cpu().numpy() for items in self.lossitems] # (write_loss) ⋅ n_names
        if self.memmaps is None:
            tmp = []
            for (id_str, names, items), data in zip(self.wrapped, [inputs, outputs, loss]):
                for name, d in zip(names, data):
                    file = f"{REPLAYPATH}{name}.dat"
                    if os.path.isfile(file):
                        os.remove(file)
                    shape = list(d.shape)   # (write_loss_period, n_parallel, replay_length, n_symmetries, 9) | 
                                            # (write_loss_period, n_parallel, replay_length, n_symmetries) |
                                            # (write_loss_period)
                    shape[0] = self.max_rows # (max_rows, n_parallel, replay_length ...)
                    mm = np.memmap(
                        filename=file,
                        dtype=(np.int32 if id_str=="inputs" else np.float32),
                        mode="w+",
                        shape=tuple(shape)
                    )
                    tmp.append((name, mm))
            self.memmaps = dict(tmp)
        
        names_shapes_datatypes: list[dict] = []
        write_loss_period = inputs[0].shape[0] # write_loss_period
        new_idx = self.steps_taken+write_loss_period
        for (id_str, names, items), data in zip(self.wrapped, [inputs, outputs, loss]):
            for name, d in zip(names, data):
                mm=self.memmaps[name]
                names_shapes_datatypes.append({
                    'name':name, 
                    'shape': d.shape,
                    'dtype': str(np.int32 if id_str=="inputs" else np.float32),
                    })
                mm[self.steps_taken:new_idx] = d
                mm.flush()
        self.steps_taken = new_idx

        with open(f"{REPLAYPATH}metadata.json", "w") as file:
            metadata = {
                'steps': self.steps_taken,
                'items': names_shapes_datatypes
                }
            json.dump(metadata, file, indent=4)